export interface ProductionAsset extends CoverAsset {schemaVersion:string;visible_scene?:string[];activity_suitability?:string[];editorial_mood?:string[];assetRole:string;geoSpecificity:string;actualCaptureGeo:{entityIds:string[];countryCodes:string[];regionIds:string[];label:string;source:string;evidence:string;confidence:string};landmarkVisibility:'none'|'incidental'|'recognizable'|'dominant';landmarkAssessment:string;recommendationEligibility:{generic:boolean;regional:boolean;exactGeoIds:string[];quarantined:boolean;source:string};sceneTags:string[];activityTags:string[];moodTags:string[];seasonTags:string[];timeOfDay:string;paletteTags:string[];composition:{kind:string;focalX:number;focalY:number;textSafeArea:string;heroCropVerified:boolean;cropReview:{wide16x9:string;mobile4x5:string;note:string}};visualFamily:string;subject:string;primaryScene:string;provenance:{kind:string;author:string;sourceUrl:string;license:string;licenseUrl:string;attribution:string;sha256:string;rightsReview:string;humanReview:string;agentQA:string}}
